**OffPeak:**

```php
final class OffPeak
{
    public function __construct(
        public readonly Decimal $multiplier,
        private readonly int $windowStartMinutes,
        private readonly int $windowEndMinutes,
    ) {}

    public static function fromInput(string $windowStart, string $windowEnd, string $multiplier): self
    {
        $start = self::parseTimeOfDay($windowStart, 'window_start');
        $end = self::parseTimeOfDay($windowEnd, 'window_end');
        return new self(Decimal::of($multiplier), $start, $end);
    }

    public function isOffPeak(DateTimeImmutable $utcTs): bool
    {
        $t = $utcTs->getHour() * 60 + $utcTs->getMinute();
        [$start, $end] = [$this->windowStartMinutes, $this->windowEndMinutes];
        return $start <= $end
            ? ($t >= $start && $t < $end)
            : ($t >= $start || $t < $end);
    }

    public static function parseTimeOfDay(string $t, string $field): int
    {
        if (preg_match('/^([01]?\d|2[0-3]):([0-5]\d)$/', $t, $m) !== 1) {
            throw new ImportException(sprintf('Field "%s" must be "HH:MM", got "%s".', $field, $t));
        }
        return (int) $m[1] * 60 + (int) $m[2];
    }
}
