private static function parseUtc(DateTimeImmutable|string $v): DateTimeImmutable
{
    if ($v instanceof DateTimeImmutable) return $v;
    try { $dt = new DateTimeImmutable((string) $v); } catch (Exception $e) { throw new ImportException(...); }
