public function ratePending(): RateRunResult
{
    return $em->wrapInTransaction(function () {
        $pending = $repo->findAllPending(); // sorted by provider, request id
        $rateCalculator = ...
        $byPair = providers cache
        $newlyRated = 0; $unrated = [];
        foreach ($pending as $event) {
            $row = $priceRepo->findApplicable($event->provider, $event->model, $event->ts);
            if ($row === null) { $unrated[] = $event; continue; }
            $providerEntity = $em->find(Provider::class, $event->provider);
            $offPeak = $providerEntity?->offPeak();
            $multiplier = ($offPeak !== null && $offPeak->isOffPeak($event->ts)) ? $offPeak->multiplier : null;
            $cost = $calculator->cost($row->price(), $event->usage(), $multiplier)->round(Billing::COST_DECIMALS);
            $event->markRated($cost, $row->id, new DateTimeImmutable('now'));
            $newlyRated++;
        }
        $em->flush();
        return new RateRunResult($newlyRated, $unrated);
    });
}
```

