final class RateCalculator
{
    public function baseCost(Price $price, TokenUsage $usage): Decimal
    {
        return match ($price->unit) {
            PricingUnit::Per1MTokens => $this->perTokenKinds($price, $usage),
            PricingUnit::Per1MTokensUnified => Decimal::of($usage->total())
                ->mul($price->rates['any'])
                ->div(Decimal::of(1_000_000)),
        };
    }

    private function perTokenKinds(Price $price, TokenUsage $usage): Decimal
    {
        return Decimal::zero()
            ->add($this->kind(usage.input, price.rates['input']))...
    }

    private function kind(int $tokens, Decimal $rate): Decimal
