    self::$pricesImporter->import(self::$priceParser->parse(<<<'JSON'
    {
      "providers": [
        { "code": "op-test", "name": "OffPeak Test",
          "off_peak": { "window_start": "16:30", "window_end": "00:30", "multiplier": "0.5" } }
      ],
      "models": [ { "provider": "op-test", "code": "m1" } ],
